#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    unordered_map<string, int> cnt;
    cnt.reserve(N * 2);

    for (int i = 0; i < N; ++i) {
        string s;
        cin >> s;
        ++cnt[s];
    }

    long long ans = 0;

    for (const auto &entry : cnt) {
        const string &s = entry.first;
        int c = entry.second;
        long long total = 0;
        int L = (int)s.size();

        for (int i = 0; i < L; ++i) {
            for (int j = i; j < L; ++j) {
                string sub = s.substr(i, j - i + 1);
                auto it = cnt.find(sub);
                if (it != cnt.end()) {
                    total += it->second;
                }
            }
        }

        ans += 1LL * c * (total - 1);
    }

    cout << ans << '\n';
    return 0;
}
